fn look_for_min(a: &[i32], i: usize) -> usize {
    // Initialize the minimum index to the starting index
    let mut min_index = i;

    // Iterate over the elements from the starting index to the end of the array
    for j in i..a.len() {
        // If the current element is less than the element at the min_index, update min_index
        if a[j] < a[min_index] {
            min_index = j;
        }
    }

    // Return the index of the minimum element found
    min_index
}

